class Solution { public int minimumTeachings(int n,int[][] languages,int[][] friendships){List<Set<Integer>> known=new ArrayList<>();for(int[] user:languages){Set<Integer> set=new HashSet<>();for(int language:user)set.add(language);known.add(set);}Set<Integer> candidates=new HashSet<>();for(int[] friendship:friendships){Set<Integer> first=known.get(friendship[0]-1),second=known.get(friendship[1]-1);boolean share=false;for(int language:first)if(second.contains(language)){share=true;break;}if(!share){candidates.add(friendship[0]-1);candidates.add(friendship[1]-1);}}int answer=candidates.size();for(int language=1;language<=n;language++){int teach=0;for(int user:candidates)if(!known.get(user).contains(language))teach++;answer=Math.min(answer,teach);}return answer;} }
